export default function MedallionBird({ className = "" }) {
  const root = useRef(null);
  const art = useRef(null);
  const pupil = useRef(null);
  // un mask par instance : deux médaillons sur la même page se voleraient l'id
  const maskId = `mb-eye-${useId().replace(/:/g, "")}`;

  useEffect(() => {
    const svg = root.current;
    const artEl = art.current;
    const pupilEl = pupil.current;
    if (!svg || !artEl || !pupilEl) return undefined;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduced) return undefined;

    /*
      `quickTo` capture sa cible À LA CRÉATION : on lui passe donc les nœuds
      déjà montés, sinon GSAP journalise « target not found » et rien ne bouge.
    */
    const artRot = gsap.quickTo(artEl, "rotation", { duration: 0.9, ease: "power3.out" });
    const artX = gsap.quickTo(artEl, "x", { duration: 0.9, ease: "power3.out" });
    const artY = gsap.quickTo(artEl, "y", { duration: 0.9, ease: "power3.out" });
    // l'œil réagit plus vite que le médaillon : c'est ce décalage qui rend vivant
    const pupilX = gsap.quickTo(pupilEl, "x", { duration: 0.28, ease: "power3.out" });
    const pupilY = gsap.quickTo(pupilEl, "y", { duration: 0.28, ease: "power3.out" });

    const clamp = (v) => Math.max(-1, Math.min(1, v));

    const onMove = (e) => {
      const r = svg.getBoundingClientRect();
      if (!r.width) return;

      // rayon de réaction : proportionnel à la taille affichée, sinon un grand
      // médaillon sature avant même que le curseur ne l'atteigne
      const reach = Math.max(520, r.width * 0.9);
      const dx = clamp((e.clientX - (r.left + r.width / 2)) / reach);
      const dy = clamp((e.clientY - (r.top + r.height / 2)) / reach);

      artRot(dx * 1.5);
      artX(dx * 7);
      artY(dy * 5);

      /*
        L'œil est minuscule (disque r≈4,7 ; pupille r≈2) : le débattement
        utile est de ~2,2 unités. On borne donc la DISTANCE et pas chaque axe
        séparément — sinon la diagonale (2,2 ; 2,2) ferait sortir la pupille
        du disque par le coin.
      */
      const m = Math.hypot(dx, dy);
      const k = m > 1 ? 1 / m : 1;
      pupilX(dx * k * 2);
      pupilY(dy * k * 2);
    };

    window.addEventListener("mousemove", onMove);
    return () => window.removeEventListener("mousemove", onMove);
  }, []);

  return (
    <svg
      ref={root}
      viewBox={VIEW_BOX}
      className={className}
      role="img"
      aria-label="Médaillon floral au colibri, dont le regard suit le curseur"
    >
      <defs>
        {/*
          Le mask est référencé par le path : il vit dans SON espace utilisateur
          et suit donc l'inclinaison du groupe parent. Le rect blanc couvre
          largement le viewBox, la pupille noire y perce le trou.
        */}
        <mask id={maskId} maskUnits="userSpaceOnUse" x="-200" y="-200" width="1000" height="1000">
          <rect x="-200" y="-200" width="1000" height="1000" fill="#fff" />
          <g ref={pupil}>
            <path d={PUPIL} fill="#000" />
          </g>
        </mask>
      </defs>

      {/* le cadre est un cercle : on pivote autour de son centre */}
      <g ref={art} style={{ transformBox: "fill-box", transformOrigin: "50% 50%" }}>
        <path d={MEDALLION} fill="currentColor" mask={`url(#${maskId})`} />
      </g>
    </svg>
  );
}